const today = $now; // $now.set({ day : 15 }); add now which bring today's date
const is15th = today.day === 15;
const isLastDay = today.plus({ days : 1 }).day === 1;

if(is15th || isLastDay){
  return[{
    json:{
      runWorkflow : true,
      executionDate : today.toISODate(),
      reason: is15th ? '15th of the month' : 'Last day of the month'
    }
  }];
}

return [];
